import "server-only";
import { auth } from "@clerk/nextjs/server";
import { db } from "@/db";
import { links, clicks } from "@/db/schema";
import { eq, and } from "drizzle-orm";

/**
 * Fetches analytics for a specific link, scoped to the authenticated user.
 * Prevents IDOR by always joining with the current user's ID from auth().
 * @param linkId - The ID of the link to fetch analytics for
 * @returns Click records for the link, or null if unauthorized
 */
export async function getLinkAnalytics(linkId: string) {
  const { userId } = await auth();

  if (!userId) {
    throw new Error("Unauthorized: user is not authenticated.");
  }

  // Verify the link belongs to the current user before returning analytics
  const link = await db
    .select()
    .from(links)
    .where(and(eq(links.id, linkId), eq(links.userId, userId)))
    .limit(1);

  if (link.length === 0) {
    throw new Error("Forbidden: you do not have access to this link.");
  }

  const analytics = await db
    .select()
    .from(clicks)
    .where(eq(clicks.linkId, linkId));

  return analytics;
}

/**
 * Fetches all links belonging to the currently authenticated user only.
 * @returns Array of links scoped to the current user
 */
export async function getUserLinks() {
  const { userId } = await auth();

  if (!userId) {
    throw new Error("Unauthorized: user is not authenticated.");
  }

  return db.select().from(links).where(eq(links.userId, userId));
}
