## Issue 1 — Open Redirect Vulnerability (URL Scheme Validation)

````typescript
// filepath: c:\Users\emman\Desktop\common\workspace\linkshortenerproject\lib\validate-url.ts
/**
 * Validates a URL to ensure it only uses allowed schemes (http, https).
 * Prevents open redirect attacks via javascript: or data: URIs.
 * @param url - The URL string to validate
 * @returns true if the URL is safe to redirect to
 */
export function isSafeUrl(url: string): boolean {
  try {
    const parsed = new URL(url);
    return parsed.protocol === "http:" || parsed.protocol === "https:";
  } catch {
    return false;
  }
}

/**
 * Sanitizes and validates a destination URL before storage or redirect.
 * @param url - Raw URL input from user
 * @returns The validated URL string
 * @throws Error if the URL is invalid or uses a disallowed scheme
 */
export function validateDestinationUrl(url: string): string {
  if (!isSafeUrl(url)) {
    throw new Error(
      "Invalid URL: only http and https schemes are allowed."
    );
  }
  return url;
}
