## Issue 6 — Analytics Queries Not Scoped to Authenticated User

````typescript
// filepath: c:\Users\emman\Desktop\common\workspace\linkshortenerproject\lib\analytics.ts
import "server-only";
import { auth } from "@clerk/nextjs/server";
import { db } from "@/db";
import { links, clicks } from "@/db/schema";
import { eq, and } from "drizzle-orm";

/**
 * Fetches analytics for a specific link, scoped strictly to the authenticated user.
 * Prevents IDOR by joining against the current user's ID from auth().
 * @param linkId - The ID of the link to fetch analytics for
 * @returns Click records for the link
 * @throws Error if unauthenticated or link does not belong to the user
 */
export async function getLinkAnalytics(linkId: string) {
  const { userId } = await auth();

  if (!userId) {
    throw new Error("Unauthorized: user is not authenticated.");
  }

  // Verify ownership before returning analytics — prevents IDOR
  const [link] = await db
    .select()
    .from(links)
    .where(and(eq(links.id, linkId), eq(links.userId, userId)))
    .limit(1);

  if (!link) {
    throw new Error("Forbidden: you do not have access to this link.");
  }

  return db.select().from(clicks).where(eq(clicks.linkId, linkId));
}

/**
 * Fetches all links belonging to the currently authenticated user only.
 * @returns Array of links scoped to the current user
 * @throws Error if unauthenticated
 */
export async function getUserLinks() {
  const { userId } = await auth();

  if (!userId) {
    throw new Error("Unauthorized: user is not authenticated.");
  }

  return db.select().from(links).where(eq(links.userId, userId));
}
