import "server-only";

/**
 * Returns validated server-side environment variables.
 * Throws at startup if any required secret is missing.
 * @returns Object containing validated server secrets
 */
export function getServerEnv() {
  const DATABASE_URL = process.env.DATABASE_URL;
  const CLERK_SECRET_KEY = process.env.CLERK_SECRET_KEY;

  if (!DATABASE_URL) {
    throw new Error("Missing required environment variable: DATABASE_URL");
  }

  if (!CLERK_SECRET_KEY) {
    throw new Error(
      "Missing required environment variable: CLERK_SECRET_KEY"
    );
  }

  return { DATABASE_URL, CLERK_SECRET_KEY };
}
